// Generic authoring primitives. No brand, commerce, domain or electrical truth.
export function nodeAt(document,path){let node=document;for(const index of path){if(!Number.isInteger(index)||index<0||!node?.content?.[index])throw Error('Invalid authoring region.');node=node.content[index];}return node;}
export function containsProtected(node){return node.type?.startsWith('protected')||(node.content||[]).some(containsProtected);}
export function textEditable(node){return ['paragraph','heading'].includes(node.type)&&!containsProtected(node)&&((node.content||[]).length===0||(node.content?.length===1&&node.content[0].type==='text'));}
export function regions(document){const result=[];function walk(node,path=[]){if(node.type.startsWith('protected')){result.push({path,node,kind:'protected',editable:false});return;}if(['paragraph','heading'].includes(node.type))result.push({path,node,kind:node.type,editable:textEditable(node)});(node.content||[]).forEach((child,index)=>walk(child,[...path,index]));}walk(document);return result;}
export function replaceRegionText(document,path,text){if(typeof text!=='string'||text.length>10000||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(text))throw Error('Invalid authoring text.');const result=structuredClone(document),node=nodeAt(result,path);if(!textEditable(node))throw Error('This region is protected or requires the structured editor.');node.content=text?[{...(node.content?.[0]||{type:'text'}),text}]:[];return result;}
export const authoringContract=Object.freeze({version:1,document:['sections','blocks','relationships'],block:['type','content','properties','protected'],lifecycle:['draft','preview','immutable revision','publication'],renderer:'Adapter-owned; authoring may annotate private contexts only',future:['media','responsive properties','section insertion','component configuration','viewport preview','multiple sites']});
